-- Module 24: versioned Business OS templates with tenant-owned, additive installations.
alter table public.view_definitions drop constraint if exists view_definitions_filters_check;
alter table public.business_os_templates add column if not exists category text not null default'industry',add column if not exists minimum_plan text not null default'starter'check(minimum_plan in('starter','growth','pro')),add column if not exists icon text not null default'blocks';
create unique index business_os_templates_key_unique on public.business_os_templates(key);
comment on column public.business_os_templates.version is'Deprecated registry compatibility field. Published configuration lives in business_os_template_versions.';
comment on column public.business_os_templates.manifest is'Deprecated registry compatibility field. Published configuration lives in business_os_template_versions.';

create table public.business_os_template_versions(
 id uuid primary key default gen_random_uuid(),template_id uuid not null references public.business_os_templates(id)on delete cascade,version integer not null check(version>0),definition jsonb not null check(jsonb_typeof(definition)='object'),change_summary text not null check(char_length(btrim(change_summary))between 1 and 500),status text not null default'draft'check(status in('draft','published','retired')),published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,template_id),unique(template_id,version),check((status='published'and published_at is not null)or status<>'published')
);
create table public.business_os_installations(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,template_id uuid not null references public.business_os_templates(id)on delete restrict,installed_version_id uuid not null,terminology jsonb not null default'{}'check(jsonb_typeof(terminology)='object'),status text not null default'active'check(status in('active','uninstalled')),installed_by uuid not null references auth.users(id),installed_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id),unique(id,organization_id),foreign key(installed_version_id,template_id)references public.business_os_template_versions(id,template_id)on delete restrict
);
create table public.business_os_installation_resources(
 id uuid primary key default gen_random_uuid(),installation_id uuid not null,organization_id uuid not null,resource_type text not null check(resource_type in('module','object','field','form','view','workflow','permission','report','dashboard','setting')),resource_key text not null check(char_length(resource_key)between 1 and 180),tenant_resource_id uuid,source_version_id uuid not null references public.business_os_template_versions(id)on delete restrict,template_snapshot jsonb not null check(jsonb_typeof(template_snapshot)in('object','array','string','number','boolean','null')),installed_at timestamptz not null default now(),unique(installation_id,resource_type,resource_key),foreign key(installation_id,organization_id)references public.business_os_installations(id,organization_id)on delete cascade
);
create table public.business_os_installation_events(
 id uuid primary key default gen_random_uuid(),installation_id uuid not null,organization_id uuid not null,event text not null check(event in('installed','updated')),from_version integer,to_version integer not null,created_count integer not null default 0,preserved_count integer not null default 0,actor_id uuid not null references auth.users(id),details jsonb not null default'{}'check(jsonb_typeof(details)='object'),created_at timestamptz not null default now(),foreign key(installation_id,organization_id)references public.business_os_installations(id,organization_id)on delete cascade
);
create index business_os_versions_published_idx on public.business_os_template_versions(template_id,version desc)where status='published';create index business_os_install_resources_idx on public.business_os_installation_resources(organization_id,resource_type,resource_key);create index business_os_install_events_idx on public.business_os_installation_events(installation_id,created_at desc);
create trigger set_updated_at before update on public.business_os_template_versions for each row execute function private.set_updated_at();create trigger set_updated_at before update on public.business_os_installations for each row execute function private.set_updated_at();

create function private.business_os_definition_is_valid(value jsonb)returns boolean language plpgsql immutable set search_path='' as $$declare item jsonb;object_item jsonb;field_item jsonb;begin
 if jsonb_typeof(value)<>'object'or value-array['terminology','modules','objects','workflows','permissions','dashboards','reports','settings']::text[]<>'{}'::jsonb or not(value?&array['terminology','modules','objects','workflows','permissions','dashboards','reports','settings'])or jsonb_typeof(value->'terminology')<>'object'or jsonb_typeof(value->'modules')<>'array'or jsonb_typeof(value->'objects')<>'array'or jsonb_typeof(value->'workflows')<>'array'or jsonb_typeof(value->'permissions')<>'array'or jsonb_typeof(value->'dashboards')<>'array'or jsonb_typeof(value->'reports')<>'array'or jsonb_typeof(value->'settings')<>'object'or jsonb_array_length(value->'modules')>50 or jsonb_array_length(value->'objects')>100 or jsonb_array_length(value->'workflows')>100 then return false;end if;
 for item in select entry.element from jsonb_array_elements(value->'modules')entry(element)loop if item-array['key','config']::text[]<>'{}'::jsonb or not(item?&array['key','config'])or item->>'key'!~'^[a-z][a-z0-9_]*$'or jsonb_typeof(item->'config')<>'object'then return false;end if;end loop;
 for object_item in select entry.element from jsonb_array_elements(value->'objects')entry(element)loop if object_item-array['key','singularLabel','pluralLabel','description','fields','forms','views']::text[]<>'{}'::jsonb or not(object_item?&array['key','singularLabel','pluralLabel','description','fields','forms','views'])or object_item->>'key'!~'^[a-z][a-z0-9_]{0,63}$'or char_length(btrim(object_item->>'singularLabel'))not between 1 and 120 or jsonb_typeof(object_item->'fields')<>'array'or jsonb_typeof(object_item->'forms')<>'array'or jsonb_typeof(object_item->'views')<>'array'then return false;end if;for field_item in select entry.element from jsonb_array_elements(object_item->'fields')entry(element)loop if not(field_item?&array['key','label','dataType','required','unique','config'])or field_item->>'key'!~'^[a-z][a-z0-9_]{0,63}$'or field_item->>'dataType'not in('text','textarea','number','decimal','currency','percentage','boolean','date','datetime','email','phone','url','select','multiselect','status','user','branch','relation','attachment')or jsonb_typeof(field_item->'config')<>'object'then return false;end if;end loop;end loop;
 return true;exception when others then return false;end;$$;
alter table public.business_os_template_versions add constraint business_os_template_definition_valid check(private.business_os_definition_is_valid(definition));
create function private.reject_published_template_version_mutation()returns trigger language plpgsql set search_path='' as $$begin if old.status='published'then raise exception'Published Business OS versions are immutable.'using errcode='P0001';end if;return case when tg_op='DELETE'then old else new end;end;$$;create trigger immutable_published_business_os_version before update or delete on public.business_os_template_versions for each row execute function private.reject_published_template_version_mutation();

create function private.install_business_os_template(requested_organization_id uuid,requested_version_id uuid)returns uuid language plpgsql security definer set search_path='' as $$
declare actor uuid:=(select auth.uid());version_row public.business_os_template_versions%rowtype;template_row public.business_os_templates%rowtype;installation public.business_os_installations%rowtype;definition jsonb;item jsonb;object_item jsonb;field_item jsonb;form_item jsonb;view_item jsonb;workflow_item jsonb;permission_item jsonb;report_item jsonb;dashboard_item jsonb;object_id uuid;field_id uuid;form_id uuid;resource_id uuid;module_value uuid;role_id uuid;permission_key text;sections_value jsonb;section_item jsonb;field_key text;created_count integer:=0;preserved_count integer:=0;previous_version integer;event_value text;setting_value jsonb;
begin
 if actor is null or not private.can_business_permission(requested_organization_id,'template.apply',null)then raise exception'Permission denied.'using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(requested_organization_id::text,0));select*into version_row from public.business_os_template_versions where id=requested_version_id and status='published';if version_row.id is null or not private.business_os_definition_is_valid(version_row.definition)then raise exception'Published Business OS version not found or invalid.'using errcode='22023';end if;select*into template_row from public.business_os_templates where id=version_row.template_id and status='published';if template_row.id is null then raise exception'Business OS template is unavailable.'using errcode='22023';end if;select*into installation from public.business_os_installations where organization_id=requested_organization_id for update;if installation.id is not null and installation.template_id<>template_row.id then raise exception'This Business already has a different Business OS installed.'using errcode='P0001';end if;if installation.id is not null and(select version from public.business_os_template_versions where id=installation.installed_version_id)>=version_row.version then return installation.id;end if;definition:=version_row.definition;
 if installation.id is null then insert into public.business_os_installations(organization_id,template_id,installed_version_id,terminology,installed_by)values(requested_organization_id,template_row.id,version_row.id,definition->'terminology',actor)returning*into installation;event_value:='installed';else select version into previous_version from public.business_os_template_versions where id=installation.installed_version_id;update public.business_os_installations set installed_version_id=version_row.id,terminology=(definition->'terminology')||terminology,status='active'where id=installation.id returning*into installation;event_value:='updated';end if;
 for item in select value from jsonb_array_elements(definition->'modules')loop select module.id into module_value from public.module_definitions module where module.key=item->>'key'and module.status='published';if module_value is null then raise exception'Template module % is unavailable.',item->>'key'using errcode='22023';end if;if exists(select 1 from public.organization_modules assignment where assignment.organization_id=requested_organization_id and assignment.module_id=module_value)then preserved_count:=preserved_count+1;else perform private.set_business_module_state(requested_organization_id,item->>'key',true,item->'config');update public.organization_modules assignment set source_template_id=template_row.id where assignment.organization_id=requested_organization_id and assignment.module_id=module_value;created_count:=created_count+1;end if;insert into public.business_os_installation_resources(installation_id,organization_id,resource_type,resource_key,tenant_resource_id,source_version_id,template_snapshot)values(installation.id,requested_organization_id,'module',item->>'key',module_value,version_row.id,item)on conflict do nothing;end loop;
 for object_item in select value from jsonb_array_elements(definition->'objects')loop select id into object_id from public.object_definitions where organization_id=requested_organization_id and key=object_item->>'key';if object_id is null then insert into public.object_definitions(organization_id,key,singular_label,plural_label,description,status,config)values(requested_organization_id,object_item->>'key',object_item->>'singularLabel',object_item->>'pluralLabel',nullif(object_item->>'description',''),'active',jsonb_build_object('source','template','templateVersionId',version_row.id))returning id into object_id;created_count:=created_count+1;else preserved_count:=preserved_count+1;end if;insert into public.business_os_installation_resources(installation_id,organization_id,resource_type,resource_key,tenant_resource_id,source_version_id,template_snapshot)values(installation.id,requested_organization_id,'object',object_item->>'key',object_id,version_row.id,object_item)on conflict do nothing;
  for field_item in select value from jsonb_array_elements(object_item->'fields')loop select id into field_id from public.field_definitions where organization_id=requested_organization_id and object_definition_id=object_id and key=field_item->>'key';if field_id is null then insert into public.field_definitions(organization_id,object_definition_id,key,label,data_type,is_required,is_unique,sort_order,config)values(requested_organization_id,object_id,field_item->>'key',field_item->>'label',field_item->>'dataType',coalesce((field_item->>'required')::boolean,false),coalesce((field_item->>'unique')::boolean,false),coalesce((field_item->>'sortOrder')::integer,0),(field_item->'config')||jsonb_build_object('source','template'))returning id into field_id;created_count:=created_count+1;else preserved_count:=preserved_count+1;end if;insert into public.business_os_installation_resources(installation_id,organization_id,resource_type,resource_key,tenant_resource_id,source_version_id,template_snapshot)values(installation.id,requested_organization_id,'field',(object_item->>'key')||'.'||(field_item->>'key'),field_id,version_row.id,field_item)on conflict do nothing;end loop;
  for form_item in select value from jsonb_array_elements(object_item->'forms')loop select id into form_id from public.form_definitions where organization_id=requested_organization_id and object_definition_id=object_id and key=form_item->>'key';if form_id is null then insert into public.form_definitions(organization_id,object_definition_id,key,name,description,mode,status,created_by,updated_by)values(requested_organization_id,object_id,form_item->>'key',form_item->>'name',nullif(form_item->>'description',''),coalesce(form_item->>'mode','create'),'active',actor,actor)returning id into form_id;sections_value:='[]';for section_item in select value from jsonb_array_elements(form_item->'sections')loop sections_value:=sections_value||jsonb_build_array(jsonb_build_object('key',section_item->>'key','title',section_item->>'title','description',coalesce(section_item->>'description',''),'columns',coalesce((section_item->>'columns')::integer,1),'fields',(select coalesce(jsonb_agg(jsonb_build_object('fieldId',field.id,'width','full','required',field.is_required,'readOnly',false)order by keys.ordinality),'[]')from jsonb_array_elements_text(section_item->'fieldKeys')with ordinality keys(key,ordinality)join public.field_definitions field on field.organization_id=requested_organization_id and field.object_definition_id=object_id and field.key=keys.key)));end loop;insert into public.form_layouts(organization_id,form_definition_id,sections)values(requested_organization_id,form_id,sections_value);created_count:=created_count+1;else preserved_count:=preserved_count+1;end if;insert into public.business_os_installation_resources(installation_id,organization_id,resource_type,resource_key,tenant_resource_id,source_version_id,template_snapshot)values(installation.id,requested_organization_id,'form',(object_item->>'key')||'.'||(form_item->>'key'),form_id,version_row.id,form_item)on conflict do nothing;end loop;
  for view_item in select value from jsonb_array_elements(object_item->'views')loop select id into resource_id from public.view_definitions where organization_id=requested_organization_id and object_definition_id=object_id and key=view_item->>'key';if resource_id is null then insert into public.view_definitions(organization_id,object_definition_id,key,name,description,view_type,selected_columns,filters,configuration,scope,owner_user_id,status)values(requested_organization_id,object_id,view_item->>'key',view_item->>'name',nullif(view_item->>'description',''),coalesce(view_item->>'viewType','table'),array(select jsonb_array_elements_text(view_item->'selectedColumns')),coalesce(view_item->'filters','[]'),coalesce(view_item->'configuration','{}'),'shared',actor,'active')returning id into resource_id;created_count:=created_count+1;else preserved_count:=preserved_count+1;end if;insert into public.business_os_installation_resources(installation_id,organization_id,resource_type,resource_key,tenant_resource_id,source_version_id,template_snapshot)values(installation.id,requested_organization_id,'view',(object_item->>'key')||'.'||(view_item->>'key'),resource_id,version_row.id,view_item)on conflict do nothing;end loop;
 end loop;
 for workflow_item in select value from jsonb_array_elements(definition->'workflows')loop select id into resource_id from public.workflow_definitions where organization_id=requested_organization_id and key=workflow_item->>'key'and status<>'archived'order by version desc limit 1;if resource_id is null then if not private.workflow_configuration_is_valid(workflow_item->'trigger',workflow_item->'conditions',workflow_item->'actions',workflow_item->'retryPolicy')then raise exception'Invalid template workflow.'using errcode='22023';end if;resource_id:=private.save_workflow_definition(requested_organization_id,workflow_item->>'key',workflow_item->>'name',coalesce(workflow_item->>'description',''),workflow_item->'trigger',workflow_item->'conditions',workflow_item->'actions',workflow_item->'retryPolicy',coalesce(workflow_item->>'status','draft'),null);created_count:=created_count+1;else preserved_count:=preserved_count+1;end if;insert into public.business_os_installation_resources(installation_id,organization_id,resource_type,resource_key,tenant_resource_id,source_version_id,template_snapshot)values(installation.id,requested_organization_id,'workflow',workflow_item->>'key',resource_id,version_row.id,workflow_item)on conflict do nothing;end loop;
 for permission_item in select value from jsonb_array_elements(definition->'permissions')loop select id into role_id from public.roles where organization_id=requested_organization_id and key=permission_item->>'roleKey';if role_id is null then raise exception'Template role not found.'using errcode='22023';end if;for permission_key in select jsonb_array_elements_text(permission_item->'permissionKeys')loop if not exists(select 1 from public.permissions permission where permission.key=permission_key)then raise exception'Template permission not found.'using errcode='22023';end if;insert into public.role_permissions(role_id,permission_id)select role_id,permission.id from public.permissions permission where permission.key=permission_key on conflict do nothing;end loop;insert into public.business_os_installation_resources(installation_id,organization_id,resource_type,resource_key,tenant_resource_id,source_version_id,template_snapshot)values(installation.id,requested_organization_id,'permission',permission_item->>'roleKey',role_id,version_row.id,permission_item)on conflict do nothing;end loop;
 for report_item in select value from jsonb_array_elements(definition->'reports')loop select id into resource_id from public.report_definitions where organization_id=requested_organization_id and key=report_item->>'key';if resource_id is null then insert into public.report_definitions(organization_id,key,name,description,query_config,visualization_config,status)values(requested_organization_id,report_item->>'key',report_item->>'name',nullif(report_item->>'description',''),report_item->'queryConfig',report_item->'visualizationConfig','active')returning id into resource_id;created_count:=created_count+1;else preserved_count:=preserved_count+1;end if;insert into public.business_os_installation_resources(installation_id,organization_id,resource_type,resource_key,tenant_resource_id,source_version_id,template_snapshot)values(installation.id,requested_organization_id,'report',report_item->>'key',resource_id,version_row.id,report_item)on conflict do nothing;end loop;
 for dashboard_item in select value from jsonb_array_elements(definition->'dashboards')loop select id into resource_id from public.dashboard_definitions where organization_id=requested_organization_id and key=dashboard_item->>'key';if resource_id is null then insert into public.dashboard_definitions(organization_id,key,name,description,layout_config,status)values(requested_organization_id,dashboard_item->>'key',dashboard_item->>'name',nullif(dashboard_item->>'description',''),dashboard_item->'layoutConfig','active')returning id into resource_id;created_count:=created_count+1;else preserved_count:=preserved_count+1;end if;insert into public.business_os_installation_resources(installation_id,organization_id,resource_type,resource_key,tenant_resource_id,source_version_id,template_snapshot)values(installation.id,requested_organization_id,'dashboard',dashboard_item->>'key',resource_id,version_row.id,dashboard_item)on conflict do nothing;end loop;
 setting_value:=definition->'settings';if event_value='installed'and setting_value<>'{}'then update public.business_settings set locale=coalesce(setting_value->>'locale',locale),date_format=coalesce(setting_value->>'dateFormat',date_format),week_starts_on=coalesce((setting_value->>'weekStartsOn')::integer,week_starts_on),fiscal_year_start_month=coalesce((setting_value->>'fiscalYearStartMonth')::integer,fiscal_year_start_month)where organization_id=requested_organization_id;insert into public.business_os_installation_resources(installation_id,organization_id,resource_type,resource_key,source_version_id,template_snapshot)values(installation.id,requested_organization_id,'setting','business_defaults',version_row.id,setting_value)on conflict do nothing;end if;
 insert into public.business_os_installation_events(installation_id,organization_id,event,from_version,to_version,created_count,preserved_count,actor_id,details)values(installation.id,requested_organization_id,event_value,previous_version,version_row.version,created_count,preserved_count,actor,jsonb_build_object('strategy','additive_preserve_existing'));return installation.id;
end;$$;
create function public.install_business_os_template(requested_organization_id uuid,requested_version_id uuid)returns uuid language sql security definer set search_path='' as $$select private.install_business_os_template(requested_organization_id,requested_version_id);$$;

alter table public.business_os_template_versions enable row level security;alter table public.business_os_installations enable row level security;alter table public.business_os_installation_resources enable row level security;alter table public.business_os_installation_events enable row level security;
drop policy if exists templates_select_authenticated on public.business_os_templates;create policy templates_select_authenticated on public.business_os_templates for select to authenticated using(status='published');create policy business_os_versions_read on public.business_os_template_versions for select to authenticated using(status='published');create policy business_os_installations_read on public.business_os_installations for select to authenticated using(private.can_business_permission(organization_id,'template.apply',null)or private.can_business_permission(organization_id,'module.read',null));create policy business_os_resources_read on public.business_os_installation_resources for select to authenticated using(private.can_business_permission(organization_id,'template.apply',null)or private.can_business_permission(organization_id,'module.read',null));create policy business_os_events_read on public.business_os_installation_events for select to authenticated using(private.can_business_permission(organization_id,'template.apply',null)or private.can_business_permission(organization_id,'module.read',null));
revoke all on table public.business_os_template_versions,public.business_os_installations,public.business_os_installation_resources,public.business_os_installation_events from public,anon,authenticated;grant select on table public.business_os_template_versions,public.business_os_installations,public.business_os_installation_resources,public.business_os_installation_events to authenticated;
revoke all on function private.business_os_definition_is_valid(jsonb),private.reject_published_template_version_mutation(),private.install_business_os_template(uuid,uuid)from public,anon,authenticated;revoke all on function public.install_business_os_template(uuid,uuid)from public,anon;grant execute on function public.install_business_os_template(uuid,uuid)to authenticated;

insert into public.business_os_templates(key,name,description,industry_code,version,manifest,status,category,minimum_plan,icon)values
 ('retail-store-os','Retail Store OS','A practical starting system for sari-sari stores, minimarts, and specialty retail.','retail',1,'{}','published','retail','growth','store'),
 ('service-business-os','Service Business OS','Customer, appointment, and service operations for salons, clinics, and service SMEs.','services',1,'{}','published','services','growth','calendar')on conflict(key)do nothing;
insert into public.business_os_template_versions(template_id,version,definition,change_summary,status,published_at)select template.id,1,
 case template.key when'retail-store-os'then'{"terminology":{"customer":"Customer","sale":"Sale","inventory":"Stock"},"modules":[{"key":"sales","config":{}},{"key":"product_catalog","config":{}},{"key":"inventory","config":{"allow_negative_stock":false}},{"key":"crm","config":{}},{"key":"pos","config":{}}],"objects":[{"key":"supplier_contact","singularLabel":"Supplier Contact","pluralLabel":"Supplier Contacts","description":"Retail supplier contact directory","fields":[{"key":"name","label":"Name","dataType":"text","required":true,"unique":false,"sortOrder":0,"config":{}},{"key":"mobile","label":"Mobile","dataType":"text","required":false,"unique":false,"sortOrder":1,"config":{}}],"forms":[{"key":"supplier_contact_form","name":"Supplier Contact Form","description":"Capture supplier contacts","mode":"create","sections":[{"key":"details","title":"Details","description":"","columns":1,"fieldKeys":["name","mobile"]}]}],"views":[{"key":"all_supplier_contacts","name":"All Supplier Contacts","description":"Supplier directory","viewType":"table","selectedColumns":["name","mobile"],"filters":{"logic":"all","filters":[]},"configuration":{"sorting":[],"savedFilters":[],"search":{"enabled":true,"fieldKeys":["name","mobile"],"placeholder":"Search supplier contacts"},"pagination":{"pageSize":25},"branchFiltering":{"enabled":false,"required":false}}}]}],"workflows":[],"permissions":[{"roleKey":"manager","permissionKeys":["metadata.read","record.read","record.create","record.update"]}],"dashboards":[{"key":"retail_overview","name":"Retail Overview","description":"Retail operating dashboard","layoutConfig":{"widgets":[]}}],"reports":[{"key":"retail_sales_summary","name":"Retail Sales Summary","description":"Sales summary placeholder","queryConfig":{"source":"sales"},"visualizationConfig":{"type":"metric"}}],"settings":{"locale":"en-PH","dateFormat":"MM/dd/yyyy","weekStartsOn":1,"fiscalYearStartMonth":1}}'::jsonb
 else'{"terminology":{"customer":"Client","appointment":"Booking","job_order":"Service Ticket"},"modules":[{"key":"sales","config":{}},{"key":"crm","config":{}},{"key":"product_catalog","config":{}},{"key":"appointments","config":{"slot_minutes":30}}],"objects":[{"key":"service_intake","singularLabel":"Service Intake","pluralLabel":"Service Intakes","description":"Initial client service requirements","fields":[{"key":"request","label":"Request","dataType":"textarea","required":true,"unique":false,"sortOrder":0,"config":{}}],"forms":[],"views":[]}],"workflows":[],"permissions":[{"roleKey":"manager","permissionKeys":["appointments.read","appointments.manage","crm.read","crm.manage"]}],"dashboards":[{"key":"service_overview","name":"Service Overview","description":"Service operating dashboard","layoutConfig":{"widgets":[]}}],"reports":[],"settings":{"locale":"en-PH","dateFormat":"MM/dd/yyyy","weekStartsOn":1,"fiscalYearStartMonth":1}}'::jsonb end,
 'Initial published Business OS', 'published',now()from public.business_os_templates template where template.key in('retail-store-os','service-business-os')on conflict(template_id,version)do nothing;
comment on table public.business_os_template_versions is'Immutable published Business OS snapshots. Definitions contain declarative metadata only; no executable code.';comment on table public.business_os_installations is'Tenant-owned installation pointer and terminology overlay. Template updates use additive preserve-existing semantics.';
